// Randomise each send into treatment (80%) or holdout (20%).
// Holdout rows are logged but never messaged: they are the counterfactual.
return $input.all().map((item) => ({
  json: { ...item.json, variant: Math.random() < 0.2 ? 'holdout' : 'treatment' },
}));

